// Trending: (me too + 2 × comments + 1) / (hours since posted + 2)^1.5,
// last 30 days, not solved or rejected. Offset pages.
// (sqlc can't rewrite a parameter inside ORDER BY: the score is computed here.)
func (q *Queries) FeedTrending(ctx context.Context, arg FeedTrendingParams) ([]FeedTrendingRow, error) {
	rows, err := q.db.Query(ctx, feedTrending,
		arg.Viewer,
		arg.NowEpoch,
		arg.UniversityID,
		arg.Private,
		arg.Kinds,
		arg.Visitor,
		arg.Since,
		arg.Category,
		arg.Q,
		arg.QLike,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FeedTrendingRow{}
	for rows.Next() {
		var i FeedTrendingRow
		if err := rows.Scan(
			&i.ID,
			&i.UniversityID,
			&i.Category,
			&i.Private,
			&i.Title,
			&i.Body,
			&i.Status,
			&i.Visibility,
			&i.MeTooCount,
			&i.CommentCount,
			&i.ReportCount,
			&i.HoldReason,
			&i.RemovedReason,
			&i.DeletedByAuthor,
			&i.Named,
			&i.AuthorName,
			&i.AuthorVerified,
			&i.AuthorExists,
			&i.AuthorID,
			&i.AuthorBadge,
			&i.AuthorBadgeTier,
			&i.LocationLabel,
			&i.CreatedAt,
			&i.StatusChangedAt,
			&i.SolvedAt,
			&i.EditedAt,
			&i.ImageCount,
			&i.Thumbnail,
			&i.Kind,
			&i.CampusOnly,
			&i.PollClosesAt,
			&i.Reactions,
			&i.MyReaction,
			&i.Images,
			&i.PollOptions,
			&i.PollMyVote,
			&i.Voted,
			&i.Following,
			&i.Mine,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

