// ---- moderation queue -------------------------------------------------------------------------
func (q *Queries) Queue(ctx context.Context, arg QueueParams) ([]QueueRow, error) {
	rows, err := q.db.Query(ctx, queue,
		arg.Kind,
		arg.UniversityID,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []QueueRow{}
	for rows.Next() {
		var i QueueRow
		if err := rows.Scan(
			&i.TargetType,
			&i.IssueID,
			&i.CommentID,
			&i.UniversityID,
			&i.HoldReason,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reactionCounts = `-- name: ReactionCounts :many
SELECT reaction, count(*)::int AS n FROM issue_votes WHERE issue_id = $1 GROUP BY reaction
`

type ReactionCountsRow struct {
	Reaction string
	N        int32
}

// Counts per reaction, never who.
func (q *Queries) ReactionCounts(ctx context.Context, issueID uuid.UUID) ([]ReactionCountsRow, error) {
	rows, err := q.db.Query(ctx, reactionCounts, issueID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReactionCountsRow{}
	for rows.Next() {
		var i ReactionCountsRow
		if err := rows.Scan(&i.Reaction, &i.N); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

